<td style="border: 1px solid #999; padding: 6px 10px; vertical-align: top; width: 50%;"><pre style="margin: 0;"><code>auto f(int i) {
    return i match -&gt; std::pair&lt;int, int&gt; {
        0 =&gt; {1, 2};          // ill-formed
        _ =&gt; std::pair{3, 4}; // ok
    }
